package com.company.erp.automation;

import static com.company.erp.automation.AutomationModels.*;

import com.company.erp.audit.AuditService;
import com.company.erp.workplace.WorkplaceModels.ApprovalRequest;
import com.company.erp.workplace.WorkplaceModels.ApproverRequest;
import com.company.erp.workplace.WorkplaceService;
import java.math.BigDecimal;
import java.net.InetAddress;
import java.net.URI;
import java.time.LocalDateTime;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.UUID;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;
import tools.jackson.databind.JsonNode;
import tools.jackson.databind.ObjectMapper;

@Service
public class AutomationService {
    private final JdbcClient jdbc;private final NamedParameterJdbcTemplate named;private final AuditService audit;
    private final WorkplaceService workplace;private final ObjectMapper json;
    public AutomationService(JdbcClient jdbc,NamedParameterJdbcTemplate named,AuditService audit,WorkplaceService workplace,ObjectMapper json){this.jdbc=jdbc;this.named=named;this.audit=audit;this.workplace=workplace;this.json=json;}

    public AutomationSummary summary(UUID companyId){return new AutomationSummary(count("automation_workflows","status='ACTIVE'",companyId),count("automation_runs","started_at>=current_date",companyId),count("automation_runs","status='FAILED' and started_at>=current_date-7",companyId),count("integration_connections","status='ACTIVE'",companyId),count("integration_webhook_deliveries","status='PENDING'",companyId));}
    public List<Map<String,Object>> connections(UUID companyId){return rows("select id,code,name,connector_type,base_url,credential_reference,config_json::text config_json,status,last_checked_at,last_success_at,last_error,created_at,updated_at from integration_connections where company_id=:companyId order by name",params(companyId));}
    @Transactional public CreatedResource createConnection(UUID companyId,ConnectionRequest request,String actor){JsonNode config=parseObject(request.configJson(),"Connection config");validateOptionalHttps(request.baseUrl());UUID id=UUID.randomUUID();jdbc.sql("insert into integration_connections(id,company_id,code,name,connector_type,base_url,credential_reference,config_json,created_by_subject) values(:id,:companyId,:code,:name,:type,:baseUrl,:credential,cast(:config as jsonb),:actor)").param("id",id.toString()).param("companyId",companyId.toString()).param("code",request.code()).param("name",request.name()).param("type",request.connectorType()).param("baseUrl",blank(request.baseUrl())).param("credential",blank(request.credentialReference())).param("config",config.toString()).param("actor",actor).update();audit.write(companyId,actor,"INTEGRATION_CONNECTION_CREATED","INTEGRATION_CONNECTION",id.toString(),"{}");return new CreatedResource(id,"DRAFT");}
    @Transactional public CreatedResource setConnectionStatus(UUID companyId,UUID id,StatusRequest request,String actor){if(!Set.of("ACTIVE","DISABLED").contains(request.status()))bad("Unsupported connection status");ensure(companyId,"integration_connections",id,"Connection");jdbc.sql("update integration_connections set status=:status,last_checked_at=current_timestamp,last_success_at=case when :status='ACTIVE' then current_timestamp else last_success_at end,last_error=null,updated_at=current_timestamp where company_id=:companyId and id=:id").param("status",request.status()).param("companyId",companyId.toString()).param("id",id.toString()).update();audit.write(companyId,actor,"INTEGRATION_CONNECTION_"+request.status(),"INTEGRATION_CONNECTION",id.toString(),"{}");return new CreatedResource(id,request.status());}

    public List<Map<String,Object>> endpoints(UUID companyId){return rows("select e.id,e.connection_id,c.name connection_name,e.code,e.name,e.direction,e.event_type,e.target_url,e.enabled,e.timeout_seconds,e.max_attempts,e.created_at,e.updated_at from integration_webhook_endpoints e left join integration_connections c on c.id=e.connection_id where e.company_id=:companyId order by e.name",params(companyId));}
    @Transactional public CreatedResource createEndpoint(UUID companyId,WebhookEndpointRequest request,String actor){ensureOptional(companyId,"integration_connections",request.connectionId(),"Connection");validateOutboundUrl(request.targetUrl());UUID id=UUID.randomUUID();jdbc.sql("insert into integration_webhook_endpoints(id,company_id,connection_id,code,name,event_type,target_url,timeout_seconds,max_attempts,created_by_subject) values(:id,:companyId,:connection,:code,:name,:event,:url,:timeout,:attempts,:actor)").param("id",id.toString()).param("companyId",companyId.toString()).param("connection",uuid(request.connectionId())).param("code",request.code()).param("name",request.name()).param("event",request.eventType()).param("url",request.targetUrl()).param("timeout",request.timeoutSeconds()==null?10:request.timeoutSeconds()).param("attempts",request.maxAttempts()==null?5:request.maxAttempts()).param("actor",actor).update();audit.write(companyId,actor,"WEBHOOK_ENDPOINT_CREATED","WEBHOOK_ENDPOINT",id.toString(),"{}");return new CreatedResource(id,"ACTIVE");}
    public List<Map<String,Object>> deliveries(UUID companyId,String status){Map<String,Object>p=params(companyId);String filter=blank(status)==null?"":" and d.status=:status";if(blank(status)!=null)p.put("status",status);return rows("select d.id,d.endpoint_id,e.name endpoint_name,d.automation_run_id,d.event_type,d.payload_json::text payload_json,d.status,d.attempt_count,d.next_attempt_at,d.last_attempt_at,d.response_status,d.last_error,d.created_at,d.delivered_at from integration_webhook_deliveries d join integration_webhook_endpoints e on e.id=d.endpoint_id where d.company_id=:companyId"+filter+" order by d.created_at desc limit 200",p);}
    @Transactional public CreatedResource retryDelivery(UUID companyId,UUID deliveryId,String actor){Map<String,Object>d=one("select status from integration_webhook_deliveries where company_id=:companyId and id=:id for update",params(companyId,"id",deliveryId));if(!Set.of("FAILED","DEAD_LETTER").contains(text(d.get("status"))))bad("Only failed deliveries can be retried");jdbc.sql("update integration_webhook_deliveries set status='PENDING',next_attempt_at=current_timestamp,last_error=null where company_id=:companyId and id=:id").param("companyId",companyId.toString()).param("id",deliveryId.toString()).update();audit.write(companyId,actor,"WEBHOOK_DELIVERY_RETRIED","WEBHOOK_DELIVERY",deliveryId.toString(),"{}");return new CreatedResource(deliveryId,"PENDING");}

    public List<Map<String,Object>> workflows(UUID companyId){return rows("select w.id,w.code,w.name,w.description,w.trigger_type,w.trigger_config::text trigger_config,w.status,w.version,w.next_run_at,w.last_run_at,w.owner_subject,w.created_at,w.updated_at,(select count(*) from automation_steps s where s.workflow_id=w.id) step_count from automation_workflows w where w.company_id=:companyId order by w.updated_at desc",params(companyId));}
    public List<Map<String,Object>> steps(UUID companyId,UUID workflowId){ensure(companyId,"automation_workflows",workflowId,"Workflow");return rows("select id,step_order,name,step_type,config_json::text config_json,continue_on_error from automation_steps where company_id=:companyId and workflow_id=:workflow order by step_order",params(companyId,"workflow",workflowId));}
    @Transactional public CreatedResource createWorkflow(UUID companyId,WorkflowRequest request,String actor){JsonNode trigger=parseObject(request.triggerConfigJson(),"Trigger config");validateTrigger(request.triggerType(),trigger);UUID id=UUID.randomUUID();jdbc.sql("insert into automation_workflows(id,company_id,code,name,description,trigger_type,trigger_config,owner_subject) values(:id,:companyId,:code,:name,:description,:trigger,cast(:config as jsonb),:actor)").param("id",id.toString()).param("companyId",companyId.toString()).param("code",request.code()).param("name",request.name()).param("description",blank(request.description())).param("trigger",request.triggerType()).param("config",trigger.toString()).param("actor",actor).update();int order=0;for(WorkflowStepRequest step:request.steps()){JsonNode config=parseObject(step.configJson(),"Step config");validateStep(companyId,step.stepType(),config);jdbc.sql("insert into automation_steps(id,company_id,workflow_id,step_order,name,step_type,config_json,continue_on_error) values(:id,:companyId,:workflow,:order,:name,:type,cast(:config as jsonb),:continueOnError)").param("id",UUID.randomUUID().toString()).param("companyId",companyId.toString()).param("workflow",id.toString()).param("order",++order).param("name",step.name()).param("type",step.stepType()).param("config",config.toString()).param("continueOnError",step.continueOnError()).update();}audit.write(companyId,actor,"AUTOMATION_WORKFLOW_CREATED","AUTOMATION_WORKFLOW",id.toString(),"{}");return new CreatedResource(id,"DRAFT");}
    @Transactional public CreatedResource setWorkflowStatus(UUID companyId,UUID workflowId,StatusRequest request,String actor){if(!Set.of("ACTIVE","PAUSED","ARCHIVED").contains(request.status()))bad("Unsupported workflow status");Map<String,Object>w=one("select trigger_type,trigger_config::text trigger_config,status from automation_workflows where company_id=:companyId and id=:id for update",params(companyId,"id",workflowId));if("ARCHIVED".equals(text(w.get("status"))))bad("Archived workflow cannot be changed");long stepCount=jdbc.sql("select count(*) from automation_steps where company_id=:companyId and workflow_id=:id").param("companyId",companyId.toString()).param("id",workflowId.toString()).query(Long.class).single();if("ACTIVE".equals(request.status())&&stepCount==0)bad("Workflow must contain at least one step");LocalDateTime next="ACTIVE".equals(request.status())&&"SCHEDULE".equals(text(w.get("trigger_type")))?LocalDateTime.now().plusMinutes(interval(parseObject(text(w.get("trigger_config")),"Trigger config"))):null;jdbc.sql("update automation_workflows set status=:status,next_run_at=:next,updated_at=current_timestamp where company_id=:companyId and id=:id").param("status",request.status()).param("next",next).param("companyId",companyId.toString()).param("id",workflowId.toString()).update();audit.write(companyId,actor,"AUTOMATION_WORKFLOW_"+request.status(),"AUTOMATION_WORKFLOW",workflowId.toString(),"{}");return new CreatedResource(workflowId,request.status());}
    @Transactional public CreatedResource run(UUID companyId,UUID workflowId,RunRequest request,String actor){JsonNode input=parseObject(blank(request.inputJson())==null?"{}":request.inputJson(),"Run input");return execute(companyId,workflowId,"MANUAL",input,actor);}
    @Transactional public List<CreatedResource> emitEvent(UUID companyId,String eventType,RunRequest request,String actor){if(blank(eventType)==null)bad("Event type is required");JsonNode input=parseObject(blank(request.inputJson())==null?"{}":request.inputJson(),"Event payload");List<Map<String,Object>>matches=rows("select id from automation_workflows where company_id=:companyId and status='ACTIVE' and trigger_type='EVENT' and trigger_config->>'eventType'=:event order by created_at for update skip locked limit 50",params(companyId,"event",eventType.trim()));List<CreatedResource>runs=new ArrayList<>();for(Map<String,Object>workflow:matches)runs.add(execute(companyId,id(workflow.get("id")),"EVENT",input,actor));return runs;}
    public List<Map<String,Object>> runs(UUID companyId,UUID workflowId){Map<String,Object>p=params(companyId);String filter=workflowId==null?"":" and r.workflow_id=:workflow";if(workflowId!=null)p.put("workflow",workflowId);return rows("select r.id,r.workflow_id,w.name workflow_name,r.trigger_source,r.status,r.input_json::text input_json,r.output_json::text output_json,r.error_message,r.started_by_subject,r.started_at,r.completed_at from automation_runs r join automation_workflows w on w.id=r.workflow_id where r.company_id=:companyId"+filter+" order by r.started_at desc limit 200",p);}
    public List<Map<String,Object>> runSteps(UUID companyId,UUID runId){ensure(companyId,"automation_runs",runId,"Automation run");return rows("select rs.id,rs.step_order,s.name,s.step_type,rs.status,rs.output_json::text output_json,rs.error_message,rs.started_at,rs.completed_at from automation_run_steps rs join automation_steps s on s.id=rs.step_id where rs.company_id=:companyId and rs.run_id=:run order by rs.step_order",params(companyId,"run",runId));}

    @Scheduled(fixedDelayString="${app.automation.poll-ms:60000}") @Transactional public void runDueWorkflows(){List<Map<String,Object>>due=rows("select id,company_id from automation_workflows where status='ACTIVE' and trigger_type='SCHEDULE' and next_run_at<=current_timestamp order by next_run_at for update skip locked limit 20",new LinkedHashMap<>());for(Map<String,Object>w:due)try{execute(id(w.get("company_id")),id(w.get("id")),"SCHEDULE",parseObject("{}","Run input"),"system");}catch(Exception ignored){}}

    private CreatedResource execute(UUID companyId,UUID workflowId,String source,JsonNode input,String actor){Map<String,Object>w=one("select status,trigger_type,trigger_config::text trigger_config from automation_workflows where company_id=:companyId and id=:id for update",params(companyId,"id",workflowId));if(!"ACTIVE".equals(text(w.get("status"))))bad("Workflow is not active");UUID runId=UUID.randomUUID();jdbc.sql("insert into automation_runs(id,company_id,workflow_id,trigger_source,input_json,started_by_subject) values(:id,:companyId,:workflow,:source,cast(:input as jsonb),:actor)").param("id",runId.toString()).param("companyId",companyId.toString()).param("workflow",workflowId.toString()).param("source",source).param("input",input.toString()).param("actor",actor).update();List<Map<String,Object>>steps=rows("select id,step_order,step_type,config_json::text config_json,continue_on_error from automation_steps where company_id=:companyId and workflow_id=:workflow order by step_order",params(companyId,"workflow",workflowId));int failed=0;List<String>outputs=new ArrayList<>();for(Map<String,Object>s:steps){UUID runStep=UUID.randomUUID();jdbc.sql("insert into automation_run_steps(id,company_id,run_id,step_id,step_order,status) values(:id,:companyId,:run,:step,:order,'RUNNING')").param("id",runStep.toString()).param("companyId",companyId.toString()).param("run",runId.toString()).param("step",text(s.get("id"))).param("order",integer(s.get("step_order"))).update();try{String output=executeStep(companyId,runId,text(s.get("step_type")),parseObject(text(s.get("config_json")),"Step config"),input,actor);outputs.add(output);jdbc.sql("update automation_run_steps set status='SUCCEEDED',output_json=cast(:output as jsonb),completed_at=current_timestamp where id=:id").param("output",output).param("id",runStep.toString()).update();}catch(Exception ex){failed++;jdbc.sql("update automation_run_steps set status='FAILED',error_message=:error,completed_at=current_timestamp where id=:id").param("error",message(ex)).param("id",runStep.toString()).update();if(!bool(s.get("continue_on_error")))break;}}String finalStatus=failed==0?"SUCCEEDED":failed<steps.size()?"PARTIAL":"FAILED";String output="{\"completedSteps\":"+(steps.size()-failed)+",\"failedSteps\":"+failed+"}";jdbc.sql("update automation_runs set status=:status,output_json=cast(:output as jsonb),completed_at=current_timestamp where id=:id").param("status",finalStatus).param("output",output).param("id",runId.toString()).update();LocalDateTime next="SCHEDULE".equals(text(w.get("trigger_type")))?LocalDateTime.now().plusMinutes(interval(parseObject(text(w.get("trigger_config")),"Trigger config"))):null;jdbc.sql("update automation_workflows set last_run_at=current_timestamp,next_run_at=:next where id=:id").param("next",next).param("id",workflowId.toString()).update();audit.write(companyId,actor,"AUTOMATION_RUN_"+finalStatus,"AUTOMATION_RUN",runId.toString(),"{}");return new CreatedResource(runId,finalStatus);}
    private String executeStep(UUID companyId,UUID runId,String type,JsonNode config,JsonNode input,String actor){return switch(type){case"NOTIFICATION"->notificationStep(companyId,runId,config,actor);case"WEBHOOK"->webhookStep(companyId,runId,config,input);case"APPROVAL"->approvalStep(companyId,config,actor);default->throw new IllegalArgumentException("Unsupported automation step");};}
    private String notificationStep(UUID companyId,UUID runId,JsonNode c,String actor){String target=requiredText(c,"targetSubject"),title=requiredText(c,"title");if(!activeMember(companyId,target))bad("Notification target is not an active member");UUID id=UUID.randomUUID();jdbc.sql("insert into platform_notifications(id,company_id,target_subject,title,body,category,severity,action_path,source_type,source_id,dedupe_key,created_by_subject) values(:id,:companyId,:target,:title,:body,'AUTOMATION',:severity,:path,'AUTOMATION_RUN',:run,:dedupe,:actor) on conflict(company_id,target_subject,dedupe_key) do nothing").param("id",id.toString()).param("companyId",companyId.toString()).param("target",target).param("title",title).param("body",optionalText(c,"body")).param("severity",optionalText(c,"severity")==null?"INFO":optionalText(c,"severity")).param("path",optionalText(c,"actionPath")).param("run",runId.toString()).param("dedupe","automation:"+runId+":"+target).param("actor",actor).update();return "{\"notificationId\":\""+id+"\"}";}
    private String webhookStep(UUID companyId,UUID runId,JsonNode c,JsonNode input){UUID endpoint=requiredUuid(c,"endpointId");Map<String,Object>e=one("select event_type,enabled from integration_webhook_endpoints where company_id=:companyId and id=:id",params(companyId,"id",endpoint));if(!bool(e.get("enabled")))bad("Webhook endpoint is disabled");JsonNode payload=c.has("payload")&&c.get("payload").isObject()?c.get("payload"):input;UUID id=UUID.randomUUID();jdbc.sql("insert into integration_webhook_deliveries(id,company_id,endpoint_id,automation_run_id,event_type,payload_json) values(:id,:companyId,:endpoint,:run,:event,cast(:payload as jsonb))").param("id",id.toString()).param("companyId",companyId.toString()).param("endpoint",endpoint.toString()).param("run",runId.toString()).param("event",text(e.get("event_type"))).param("payload",payload.toString()).update();return "{\"deliveryId\":\""+id+"\"}";}
    private String approvalStep(UUID companyId,JsonNode c,String actor){List<ApproverRequest>approvers=new ArrayList<>();JsonNode values=c.get("approverSubjects");if(values==null||!values.isArray()||values.isEmpty())bad("Approval step requires approverSubjects");for(JsonNode value:values)approvers.add(new ApproverRequest(value.asText()));BigDecimal amount=c.hasNonNull("amount")?c.get("amount").decimalValue():null;var created=workplace.createApproval(companyId,new ApprovalRequest(optionalText(c,"requestType")==null?"AUTOMATION":optionalText(c,"requestType"),requiredText(c,"title"),optionalText(c,"description"),"AUTOMATION",null,null,null,amount,amount==null?null:requiredText(c,"currency"),approvers),actor);workplace.submitApproval(companyId,created.id(),actor);return "{\"approvalId\":\""+created.id()+"\"}";}

    private void validateTrigger(String type,JsonNode config){if("SCHEDULE".equals(type))interval(config);if("EVENT".equals(type))requiredText(config,"eventType");}
    private void validateStep(UUID companyId,String type,JsonNode config){switch(type){case"NOTIFICATION"->{requiredText(config,"targetSubject");requiredText(config,"title");}case"WEBHOOK"->{UUID endpoint=requiredUuid(config,"endpointId");ensure(companyId,"integration_webhook_endpoints",endpoint,"Webhook endpoint");}case"APPROVAL"->{requiredText(config,"title");JsonNode values=config.get("approverSubjects");if(values==null||!values.isArray()||values.isEmpty())bad("Approval step requires approverSubjects");}default->bad("Unsupported step type");}}
    private int interval(JsonNode config){int value=config.path("intervalMinutes").asInt(0);if(value<1||value>10080)bad("Schedule intervalMinutes must be between 1 and 10080");return value;}
    private void validateOptionalHttps(String value){if(blank(value)!=null)validateOutboundUrl(value);}
    private void validateOutboundUrl(String value){try{URI uri=URI.create(value);if(!"https".equalsIgnoreCase(uri.getScheme())||uri.getHost()==null||uri.getUserInfo()!=null)bad("Outbound URL must use HTTPS without embedded credentials");String host=uri.getHost().toLowerCase().replace("[","").replace("]","");if(host.equals("localhost")||host.endsWith(".local")||host.endsWith(".internal"))bad("Private webhook targets are not allowed");if(host.contains(":")||host.matches("[0-9.]+")){InetAddress address=InetAddress.getByName(host);if(address.isAnyLocalAddress()||address.isLoopbackAddress()||address.isLinkLocalAddress()||address.isSiteLocalAddress())bad("Private webhook targets are not allowed");}}catch(ResponseStatusException ex){throw ex;}catch(Exception ex){bad("Outbound URL is invalid");}}
    private boolean activeMember(UUID companyId,String subject){return jdbc.sql("select count(*) from company_memberships where company_id=:companyId and keycloak_subject=:subject and status='ACTIVE'").param("companyId",companyId.toString()).param("subject",subject).query(Integer.class).single()>0;}
    private long count(String table,String condition,UUID companyId){return jdbc.sql("select count(*) from "+table+" where company_id=:companyId and "+condition).param("companyId",companyId.toString()).query(Long.class).single();}
    private void ensure(UUID companyId,String table,UUID id,String label){if(!Set.of("integration_connections","integration_webhook_endpoints","automation_workflows","automation_runs").contains(table)||id==null||jdbc.sql("select count(*) from "+table+" where company_id=:companyId and id=:id").param("companyId",companyId.toString()).param("id",id.toString()).query(Integer.class).single()==0)notFound(label+" not found");}
    private void ensureOptional(UUID companyId,String table,UUID id,String label){if(id!=null)ensure(companyId,table,id,label);}
    private JsonNode parseObject(String value,String label){try{JsonNode node=json.readTree(value);if(!node.isObject())bad(label+" must be a JSON object");return node;}catch(ResponseStatusException ex){throw ex;}catch(Exception ex){bad(label+" is invalid JSON");return null;}}
    private Map<String,Object>params(UUID companyId,Object...pairs){Map<String,Object>p=new LinkedHashMap<>();p.put("companyId",companyId.toString());for(int i=0;i<pairs.length;i+=2)p.put(String.valueOf(pairs[i]),pairs[i+1] instanceof UUID u?u.toString():pairs[i+1]);return p;}
    private List<Map<String,Object>>rows(String sql,Map<String,Object>p){return named.queryForList(sql,p);}private Map<String,Object>one(String sql,Map<String,Object>p){List<Map<String,Object>>r=rows(sql,p);if(r.isEmpty())notFound("Automation record not found");return r.getFirst();}
    private static String requiredText(JsonNode node,String key){String value=optionalText(node,key);if(value==null)bad(key+" is required");return value;}private static UUID requiredUuid(JsonNode node,String key){try{return UUID.fromString(requiredText(node,key));}catch(ResponseStatusException ex){throw ex;}catch(Exception ex){bad(key+" must be a valid UUID");return null;}}private static String optionalText(JsonNode node,String key){return node.hasNonNull(key)&&!node.get(key).asText().isBlank()?node.get(key).asText().trim():null;}private static String blank(String value){return value==null||value.isBlank()?null:value.trim();}private static String uuid(UUID value){return value==null?null:value.toString();}private static UUID id(Object value){return value==null?null:UUID.fromString(value.toString().trim());}private static int integer(Object value){return Integer.parseInt(value.toString());}private static boolean bool(Object value){return value instanceof Boolean b?b:Boolean.parseBoolean(text(value));}private static String text(Object value){return value==null?"":value.toString();}private static String message(Exception ex){String value=ex instanceof ResponseStatusException r?r.getReason():ex.getMessage();return value==null?"Automation step failed":value.substring(0,Math.min(1900,value.length()));}private static void bad(String message){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,message);}private static void notFound(String message){throw new ResponseStatusException(HttpStatus.NOT_FOUND,message);}
}
